     1→/**
     2→ * Route Compiler — Core Engine
     3→ *
     4→ * Pure functions for compiling URL patterns, matching URLs against a registry,
     5→ * and building URLs from patterns + params.
     6→ *
     7→ * Pattern syntax:
     8→ *   /workspace/:workspaceId        — named param (matches one segment)
     9→ *   /workspace/:workspaceId/pages/:pageSlug+  — rest param (matches 1+ segments)
    10→ */
    11→
    12→import type { IconData } from "@/components/ui/icon-picker";
    13→
    14→// ─── Types ───────────────────────────────────────────────────────────────────
    15→
    16→export interface CompiledPattern {
    17→  pattern: string;
    18→  regex: RegExp;
    19→  paramNames: string[];
    20→  restParam: string | null;
    21→  build: (params: Record<string, string>) => string;
    22→  constantSegmentCount: number;
    23→}
    24→
    25→export interface RouteEntry<TParams extends Record<string, string> = Record<string, string>> {
    26→  pattern: string;
    27→  icon: IconData | ((params: TParams) => IconData);
    28→  title: string | ((params: TParams) => string);
    29→  titleKey?: string;
    30→  isContainer?: boolean;
    31→  queryParams?: string[];
    32→  dropdownCategory?: string;
    33→}
    34→
    35→export interface RouteMatch {
    36→  pattern: string;
    37→  params: Record<string, string>;
    38→  icon: IconData;
    39→  title: string;
    40→  entry: RouteEntry;
    41→}
    42→
    43→export interface CompiledRoute extends CompiledPattern {
    44→  entry: RouteEntry;
    45→  queryParams: string[];
    46→}
    47→
    48→// ─── Core: compilePattern ────────────────────────────────────────────────────
    49→
    50→export function compilePattern(pattern: string): CompiledPattern {
    51→  const paramNames: string[] = [];
    52→  let restParam: string | null = null;
    53→  let constantSegmentCount = 0;
    54→
    55→  const segments = pattern.split("/").filter(Boolean);
    56→  const regexParts: string[] = [];
    57→  const buildParts: Array<
    58→    | { type: "const"; value: string }
    59→    | { type: "param"; name: string; rest: boolean }
    60→  > = [];
    61→
    62→  for (const segment of segments) {
    63→    if (segment.startsWith(":")) {
    64→      const isRest = segment.endsWith("+");
    65→      const name = isRest ? segment.slice(1, -1) : segment.slice(1);
    66→      paramNames.push(name);
    67→      if (isRest) {
    68→        restParam = name;
    69→        regexParts.push("(.+)");
    70→      } else {
    71→        regexParts.push("([^/]+)");
    72→      }
    73→      buildParts.push({ type: "param", name, rest: isRest });
    74→    } else {
    75→      constantSegmentCount++;
    76→      regexParts.push(escapeRegex(segment));
    77→      buildParts.push({ type: "const", value: segment });
    78→    }
    79→  }
    80→
    81→  const regex = new RegExp("^\\/" + regexParts.join("\\/") + "$");
    82→
    83→  const build = (params: Record<string, string>): string => {
    84→    const parts = buildParts.map((part) => {
    85→      if (part.type === "const") return part.value;
    86→      const value = params[part.name];
    87→      if (!value) {
    88→        throw new Error(`Param "${part.name}" must be non-empty for pattern: ${pattern}`);
    89→      }
    90→      return part.rest ? value : encodeURIComponent(value);
    91→    });
    92→    return "/" + parts.join("/");
    93→  };
    94→
    95→  return { pattern, regex, paramNames, restParam, build, constantSegmentCount };
    96→}
    97→
    98→// ─── Registry ────────────────────────────────────────────────────────────────
    99→
   100→export function compileRegistry(entries: RouteEntry[]): CompiledRoute[] {
   101→  const compiled = entries.map((entry) => ({
   102→    ...compilePattern(entry.pattern),
   103→    entry,
   104→    queryParams: entry.queryParams ?? [],
   105→  }));
   106→
   107→  // Sort: more constant segments first, then non-rest before rest
   108→  compiled.sort((a, b) => {
   109→    if (b.constantSegmentCount !== a.constantSegmentCount) {
   110→      return b.constantSegmentCount - a.constantSegmentCount;
   111→    }
   112→    return (a.restParam ? 1 : 0) - (b.restParam ? 1 : 0);
   113→  });
   114→
   115→  return compiled;
   116→}
   117→
   118→// ─── matchUrl ────────────────────────────────────────────────────────────────
   119→
   120→export function matchUrl(url: string, entries: RouteEntry[]): RouteMatch | null {
   121→  const compiled = compileRegistry(entries);
   122→  return matchUrlCompiled(url, compiled);
   123→}
   124→
   125→export function matchUrlCompiled(url: string, compiled: CompiledRoute[]): RouteMatch | null {
   126→  const parsed = new URL(url, "http://localhost");
   127→  const pathname = parsed.pathname;
   128→
   129→  for (const route of compiled) {
   130→    const pathMatch = route.regex.exec(pathname);
   131→    if (!pathMatch) continue;
   132→
   133→    const params: Record<string, string> = {};
   134→    route.paramNames.forEach((name, i) => {
   135→      const raw = pathMatch[i + 1];
   136→      params[name] =
   137→        name === route.restParam
   138→          ? raw.split("/").map(decodeURIComponent).join("/")
   139→          : decodeURIComponent(raw);
   140→    });
   141→
   142→    // Extract declared query params
   143→    for (const qp of route.queryParams) {
   144→      const value = parsed.searchParams.get(qp);
   145→      if (value) params[qp] = value;
   146→    }
   147→
   148→    return {
   149→      pattern: route.pattern,
   150→      params,
   151→      icon: resolveIcon(route.entry, params),
   152→      title: resolveTitle(route.entry, params),
   153→      entry: route.entry,
   154→    };
   155→  }
   156→  return null;
   157→}
   158→
   159→// ─── buildUrl ────────────────────────────────────────────────────────────────
   160→
   161→export function buildUrl(
   162→  pattern: string,
   163→  params: Record<string, string>,
   164→  entries: RouteEntry[],
   165→): string {
   166→  const compiled = compileRegistry(entries);
   167→  return buildUrlCompiled(pattern, params, compiled);
   168→}
   169→
   170→export function buildUrlCompiled(
   171→  pattern: string,
   172→  params: Record<string, string>,
   173→  compiled: CompiledRoute[],
   174→): string {
   175→  const route = compiled.find((r) => r.pattern === pattern);
   176→  if (!route) throw new Error(`Unknown pattern: ${pattern}`);
   177→
   178→  let path = route.build(params);
   179→
   180→  const queryEntries = route.queryParams
   181→    .filter((qp) => params[qp])
   182→    .map((qp) => [qp, params[qp]] as [string, string]);
   183→
   184→  if (queryEntries.length > 0) {
   185→    path += "?" + new URLSearchParams(queryEntries).toString();
   186→  }
   187→
   188→  return path;
   189→}
   190→
   191→// ─── Helpers ─────────────────────────────────────────────────────────────────
   192→
   193→function resolveIcon(entry: RouteEntry, params: Record<string, string>): IconData {
   194→  return typeof entry.icon === "function" ? entry.icon(params) : entry.icon;
   195→}
   196→
   197→function resolveTitle(entry: RouteEntry, params: Record<string, string>): string {
   198→  return typeof entry.title === "function" ? entry.title(params) : entry.title;
   199→}
   200→
   201→function escapeRegex(str: string): string {
   202→  return str.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
   203→}
